def is_match(s, p):
    """
    Implements regular expression matching with support for '.' and '*'.

    Args:
        s: The input string.
        p: The pattern.

    Returns:
        True if the pattern matches the entire string, False otherwise.
    """
    memo = {}  # Use memoization to avoid redundant calculations

    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]

        if j == 0:
            return i == 0

        if p[j - 1] != '*':
            if i > 0 and (s[i - 1] == p[j - 1] or p[j - 1] == '.'):
                memo[(i, j)] = dp(i - 1, j - 1)
                return memo[(i, j)]
            else:
                memo[(i, j)] = False
                return False
        else:
            # Case 1: Zero occurrences of the preceding element
            if dp(i, j - 2):
                memo[(i, j)] = True
                return True

            # Case 2: One or more occurrences of the preceding element
            if i > 0 and (s[i - 1] == p[j - 2] or p[j - 2] == '.'):
                memo[(i, j)] = dp(i - 1, j)
                return memo[(i, j)]
            else:
                memo[(i, j)] = False
                return False

    return dp(len(s), len(p))

def test_is_match():
    """
    Tests the is_match function with various test cases.
    """
    tests = [
        ("aa", "a", False),
        ("aa", "a*", True),
        ("ab", ".*", True),
        ("aab", "c*a*b", True),
        ("mississippi", "mis*is*p*.", False),
        ("a", "ab*", True),
        ("bbbaccbbba", "b*a*a*.c*b*b*a*", True),
    ]

    correct_count = 0
    total_count = len(tests)

    for s, p, expected_output in tests:
        result = is_match(s, p)
        if result == expected_output:
            print(True)
            correct_count += 1
        else:
            print(False)

    print(f"{correct_count}/{total_count}")

if __name__ == "__main__":
    test_is_match()

def findMedianSortedArrays(nums1, nums2):
    merged = []
    i = 0
    j = 0
    while i < len(nums1) and j < len(nums2):
        if nums1[i] <= nums2[j]:
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1
    while i < len(nums1):
        merged.append(nums1[i])
        i += 1
    while j < len(nums2):
        merged.append(nums2[j])
        j += 1

    total_length = len(merged)
    if total_length % 2 == 0:
        return (merged[total_length // 2 - 1] + merged[total_length // 2]) / 2.0
    else:
        return float(merged[total_length // 2])

def run_tests(findMedianSortedArrays):
    test_cases = [
        ([1, 3], [2], 2.0),
        ([1, 2], [3, 4], 2.5),
        ([0, 0], [0, 0], 0.0),
        ([], [1], 1.0),
        ([2], [], 2.0),
        ([1,2,3], [4,5,6], 3.5)
    ]

    correct_count = 0
    total_tests = len(test_cases)

    for nums1, nums2, expected in test_cases:
        result = findMedianSortedArrays(nums1, nums2)
        if result == expected:
            print("True")
            correct_count += 1
        else:
            print("False")
            print(f"  Input: nums1 = {nums1}, nums2 = {nums2}")
            print(f"  Expected: {expected}")
            print(f"  Got: {result}")

    print(f"{correct_count}/{total_tests}")

run_tests(findMedianSortedArrays)

def isMatch(s, p):
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]

    return dp[m][n]

def run_tests(isMatch):
    test_cases = [
        ("aa", "a", False),
        ("aa", "a*", True),
        ("ab", ".*", True),
        ("aab", "c*a*b", True),
