            correct_count += 1
        else:
            print("False")
            print(f"  Input: s = \"{s}\", p = \"{p}\"")
            print(f"  Expected: {expected}")
            print(f"  Got: {result}")

    print(f"{correct_count}/{total_tests}")

run_tests(isMatch)

